BASE = "7a97ab2"

head = subprocess.check_output(
    ["git", "rev-parse", "--short", "HEAD"],
    text=True,
).strip()

if head != BASE:
    raise SystemExit(
        f"Wrong baseline: HEAD is {head}, expected {BASE}."
    )

patches = [('lib/polls/notifications.ts', 'ICAgIC5mcm9tKAogICAgICAibm90aWZpY2F0aW9uX3N1cHByZXNzaW9ucyIsCiAgICApCiAgICAuc2VsZWN0KCJpZCIpCiAgICAuZXEoInNvdXJjZV90eXBlIiwgInBvbGwiKQ==', 'ICAgIC5mcm9tKAogICAgICAibm90aWZpY2F0aW9uX3N1cHByZXNzaW9ucyIsCiAgICApCiAgICAuc2VsZWN0KCJzb3VyY2VfdHlwZSIpCiAgICAuZXEoInNvdXJjZV90eXBlIiwgInBvbGwiKQ==', 'poll suppression existing-column fix'), ('app/(portal)/admin/polls/page.tsx', '', '', 'poll create anchor'), ('app/(portal)/admin/polls/page.tsx', 'ICAgICAgICAgICAgICA8ZGV0YWlscwogICAgICAgICAgICAgICAga2V5PXtwb2xsLmlkfQogICAgICAgICAgICAgICAgY2xhc3NOYW1lPSJib3JkZXIgYm9yZGVyLVtyZ2IodmFyKC0tc2VwLWNvbG91ci01OTQzMmMpKV0vNDUgYmctW3JnYih2YXIoLS1zZXAtY29sb3VyLTEwMGMwOSkpXSIKICAgICAgICAgICAgICA+', '', 'poll context metadata'), ('components/portal/admin-context-panel.tsx', 'ICB8ICJub3RpZmljYXRpb25zIgogIHwgImV4cGVyaWVuY2Ui', 'ICB8ICJub3RpZmljYXRpb25zIgogIHwgInBvbGxzIgogIHwgImV4cGVyaWVuY2Ui', 'admin context polls mode type'), ('components/portal/admin-context-panel.tsx', 'ICBpZiAocGF0aG5hbWUgPT09ICIvYWRtaW4vbm90aWZpY2F0aW9ucyIpIHsKICAgIHJldHVybiAibm90aWZpY2F0aW9ucyI7CiAgfQoKICBpZiAocGF0aG5hbWUgPT09ICIvYWRtaW4vZXhwZXJpZW5jZSIpIHs=', 'ICBpZiAocGF0aG5hbWUgPT09ICIvYWRtaW4vbm90aWZpY2F0aW9ucyIpIHsKICAgIHJldHVybiAibm90aWZpY2F0aW9ucyI7CiAgfQoKICBpZiAocGF0aG5hbWUgPT09ICIvYWRtaW4vcG9sbHMiKSB7CiAgICByZXR1cm4gInBvbGxzIjsKICB9CgogIGlmIChwYXRobmFtZSA9PT0gIi9hZG1pbi9leHBlcmllbmNlIikgew==', 'admin context polls route'), ('components/portal/admin-context-panel.tsx', 'ICBpZiAobW9kZSA9PT0gIm5vdGlmaWNhdGlvbnMiKSB7CiAgICByZXR1cm4gKAogICAgICA8QWRtaW5Ob3RpZmljYXRpb25zTmF2aWdhdG9yQ29udGV4dCAvPgogICAgKTsKICB9CgogIGlmIChtb2RlID09PSAiZXhwZXJpZW5jZSIpIHs=', 'ICBpZiAobW9kZSA9PT0gIm5vdGlmaWNhdGlvbnMiKSB7CiAgICByZXR1cm4gKAogICAgICA8QWRtaW5Ob3RpZmljYXRpb25zTmF2aWdhdG9yQ29udGV4dCAvPgogICAgKTsKICB9CgogIGlmIChtb2RlID09PSAicG9sbHMiKSB7CiAgICByZXR1cm4gKAogICAgICA8QWRtaW5Qb2xsc05hdmlnYXRvckNvbnRleHQgLz4KICAgICk7CiAgfQoKICBpZiAobW9kZSA9PT0gImV4cGVyaWVuY2UiKSB7', 'admin context polls component routing'), ('components/portal/admin-context-panel.tsx', 'dHlwZSBBZG1pblRyb3BoeUNvbnRleHRFbnRyeSA9IHsKICBpZDogc3RyaW5nOw==', '', 'insert Polls context navigator')]
cache = {}

for path, old_b64, new_b64, label in patches:
    target = Path(path)

    if not target.exists():
        raise SystemExit(
            f"Missing {path}. The polling-system patch must be applied first."
        )

    text = cache.get(
        path,
        target.read_text(encoding="utf-8"),
    )

    old = base64.b64decode(
        old_b64
    ).decode("utf-8")

    new = base64.b64decode(
        new_b64
    ).decode("utf-8")

    count = text.count(old)

    if count != 1:
        raise SystemExit(
            f"{label}: expected 1 match, found {count}."
        )

    cache[path] = text.replace(
        old,
        new,
        1,
    )

for path, text in cache.items():
    Path(path).write_text(
        text,
        encoding="utf-8",
    )
    print("✓", path)

